changeSet.sql:
CREATE TABLE etat_entretien ( id_etat_entretien SERIAL, etat_entretien VARCHAR(100) NOT NULL, niveau SMALLINT, PRIMARY KEY (id_etat_entretien), UNIQUE (niveau) );
CREATE TABLE annonce ( id_annonce SERIAL, date_annonce DATE NOT NULL, entreprise VARCHAR(50), date_expiration DATE, date_rupture DATE, id_poste INTEGER NOT NULL, PRIMARY KEY (id_annonce), FOREIGN KEY (id_poste) REFERENCES poste (id_poste) );
CREATE TABLE entretien ( id_entretien SERIAL, date_creation DATE NOT NULL, date_validation DATE, note INTEGER, motif VARCHAR(255), id_enfant INTEGER, id_annonce INTEGER NOT NULL, id_etat_entretien INTEGER NOT NULL, id_talent INTEGER NOT NULL, PRIMARY KEY (id_entretien), FOREIGN KEY (id_enfant) REFERENCES entretien (id_entretien), FOREIGN KEY (id_annonce) REFERENCES annonce (id_annonce), FOREIGN KEY (id_etat_entretien) REFERENCES etat_entretien (id_etat_entretien), FOREIGN KEY (id_talent) REFERENCES talent (id_talent) );
CREATE TABLE experience_poste ( id_poste INTEGER, id_annonce INTEGER, ans NUMERIC(10, 2), PRIMARY KEY (id_poste, id_annonce), FOREIGN KEY (id_poste) REFERENCES poste (id_poste), FOREIGN KEY (id_annonce) REFERENCES annonce (id_annonce) );
